public class LeadImportService {
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Track emails we've seen (case-insensitive, trimmed)
        Map<String, Integer> emailToFirstIndex = new Map<String, Integer>();
        List<Lead> leadsToInsert = new List<Lead>();
        Map<Integer, Integer> originalToInsertIndex = new Map<Integer, Integer>();

        // First pass: validate for duplicates, set defaults, prepare for insert
        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];
            String email = lead.Email;

            // Set LeadSource to 'Web' if blank
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }

            // Check for duplicate email
            if (String.isNotBlank(email)) {
                String normalizedEmail = email.trim().toLowerCase();

                if (emailToFirstIndex.containsKey(normalizedEmail)) {
                    // This is a duplicate
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                } else {
                    // First occurrence of this email
                    emailToFirstIndex.put(normalizedEmail, i);
                    originalToInsertIndex.put(i, leadsToInsert.size());
                    leadsToInsert.add(lead);
                }
            } else {
                // No email, so not a duplicate
                originalToInsertIndex.put(i, leadsToInsert.size());
                leadsToInsert.add(lead);
            }
        }

        // Second pass: insert all valid leads and handle database errors
        if (!leadsToInsert.isEmpty()) {
            Database.SaveResult[] saveResults = Database.insert(leadsToInsert, false);

            for (Integer i = 0; i < saveResults.size(); i++) {
                Database.SaveResult sr = saveResults[i];
                // Find the original index
                Integer originalIndex = null;
                for (Integer origIdx : originalToInsertIndex.keySet()) {
                    if (originalToInsertIndex.get(origIdx) == i) {
                        originalIndex = origIdx;
                        break;
                    }
                }

                if (sr.isSuccess()) {
                    result.successCount++;
                    result.insertedIds.add(sr.getId());
                } else {
                    // Collect all error messages
                    List<String> errorMessages = new List<String>();
                    for (Database.Error err : sr.getErrors()) {
                        errorMessages.add(err.getMessage());
                    }
                    result.errorsByIndex.put(originalIndex, String.join(errorMessages, '; '));
                }
            }
        }

        return result;
    }

    public class ImportResult {
        public Integer successCount = 0;
        public List<Id> insertedIds = new List<Id>();
        public Map<Integer, String> errorsByIndex = new Map<Integer, String>();
    }
}
