public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext ctx) {
        purgeOldLogs();
    }

    private static void purgeOldLogs() {
        // Calculate cutoff dates
        Date thirtyDaysAgo = Date.today().addDays(-30);
        Date oneHundredEightyDaysAgo = Date.today().addDays(-180);

        // Delete non-ERROR logs created more than 30 days ago
        delete [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :Datetime.newInstance(thirtyDaysAgo, Time.newInstance(0, 0, 0, 0))
            AND (Level__c != 'ERROR' OR Level__c = NULL)
        ];

        // Delete ERROR logs created more than 180 days ago
        delete [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :Datetime.newInstance(oneHundredEightyDaysAgo, Time.newInstance(0, 0, 0, 0))
            AND Level__c = 'ERROR'
        ];
    }

    public static Id scheduleNightly() {
        // Schedule to run every day at 02:00
        // Cron expression: seconds minutes hours day_of_month month day_of_week year
        // 0 0 2 * * ? * = every day at 02:00
        String cronExpression = '0 0 2 * * ? *';

        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
