```apex
public class Opportunities extends fflib_SObjectDomain {
    public Opportunities(List<SObject> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public override void onValidate() {
        // Rule 1: Amount must not be negative on insert and update
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    public override void onValidate(Map<Id, SObject> existingRecords) {
        // Rule 1: Amount must not be negative on update
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }

        // Rule 2: Amount cannot change on a won opportunity
        // (unless it's becoming won in this update)
        for (Opportunity opp : (List<Opportunity>) getRecords()) {
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);

            if (oldOpp != null) {
                // Check if the opportunity was Closed Won before this update
                boolean wasClosedWon = oldOpp.StageName == 'Closed Won';

                // Check if Amount changed
                boolean amountChanged = opp.Amount != oldOpp.Amount;

                // Error only if it was already Closed Won and Amount changed
                // (If it's becoming Closed Won now, that's allowed)
                if (wasClosedWon && amountChanged) {
                    error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                }
            }
        }
    }
}
