        fflib_QueryFactory queryFactory = newQueryFactory()
            .setCondition('Id IN :accountIds');

        new ContactsSelector().configureQueryFactoryFields(
            queryFactory,
            'Contacts'
        );

        return (List<Account>) Database.query(queryFactory.toSOQL());
    }

    protected override List<Schema.SObjectField> getAdditionalSObjectFieldList() {
        List<Schema.SObjectField> additionalFields = new List<Schema.SObjectField>();

        List<FieldSetMember> fieldSetMembers = SObjectType.Account.FieldSets.Credit_Review.getFields();
        for (FieldSetMember fieldSetMember : fieldSetMembers) {
            additionalFields.add(
                SObjectType.Account.fields.getMap().get(fieldSetMember.getFieldPath())
            );
        }

        return additionalFields;
    }
