public class AccountOnwardingService {

    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName) {

        // Return empty list if map is null or empty
        if (contactLastNamesByAccountName == null || 
            contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        // Create UnitOfWork for transactional DML
        fflib_SObjectUnitOfWork unitOfWork = 
            new fflib_SObjectUnitOfWork(
                new List<SObjectType> { Account.SObjectType, Contact.SObjectType }
            );

        List<Account> accounts = new List<Account>();

        // Iterate through each account entry
        for (String accountName : contactLastNamesByAccountName.keySet()) {
            // Create and register the Account
            Account acc = new Account(Name = accountName);
            unitOfWork.registerNew(acc);
            accounts.add(acc);

            // Get the list of contact last names for this account
            List<String> contactLastNames = contactLastNamesByAccountName.get(accountName);

            // Create and register Contacts for this account
            if (contactLastNames != null && !contactLastNames.isEmpty()) {
                for (String lastName : contactLastNames) {
                    Contact contact = new Contact(
                        LastName = lastName,
                        AccountId = acc.Id
                    );
                    unitOfWork.registerNew(contact, Contact.AccountId, acc);
                }
            }
        }

        // Commit all work in a single transaction
        unitOfWork.commitWork();

        return accounts;
    }
}
