public class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorMap = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorMap;
        }

        // Query contacts with non-null phones
        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds AND Phone != null
            FOR UPDATE
        ];

        // Normalize phone numbers
        for (Contact contact : contacts) {
            if (String.isNotBlank(contact.Phone)) {
                contact.Phone = contact.Phone.replaceAll('[^\\d+]', '');
            }
        }

        // Update with AllOrNone=false to allow partial success
        List<Database.SaveResult> results = Database.update(contacts, false);

        // Build error map from failed saves
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult result = results[i];
            if (!result.isSuccess()) {
                List<Database.Error> errors = result.getErrors();
                if (!errors.isEmpty()) {
                    errorMap.put(contacts[i].Id, errors[0].getMessage());
                }
            }
        }

        return errorMap;
    }
}
