public class RenewalReminderService {
    public static Integer sendReminders(List<Id> opportunityIds) {
        // Query opportunities to get owner IDs, names, and close dates
        List<Opportunity> opportunities = [
            SELECT Id, OwnerId, Name, CloseDate
            FROM Opportunity
            WHERE Id IN :opportunityIds
            WITH SECURITY_ENFORCED
        ];

        // Build list of email messages
        List<Messaging.SingleEmailMessage> emails = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opportunities) {
            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            email.setPlainTextBody(
                'Renewal due for ' + opp.Name + '\n' +
                'Close date: ' + (opp.CloseDate != null ? opp.CloseDate.format() : 'Not set')
            );
            emails.add(email);
        }

        // Send all emails in one call and count successful sends
        if (emails.isEmpty()) {
            return 0;
        }

        List<Messaging.SendEmailResult> results = Messaging.sendEmail(emails);
        Integer successCount = 0;

        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                successCount++;
            }
        }

        return successCount;
    }
}
```

