import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
  searchResults = [];
  errorMessage = '';
  debounceTimer;
  latestRequestId = 0;
  isConnected = true;

  disconnectedCallback() {
    this.isConnected = false;
    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = null;
    }
  }

  handleSearchChange(event) {
    const searchTerm = event.target.value.trim();

    // Clear any pending debounce timer
    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = null;
    }

    // If less than 2 characters, clear results and return
    if (searchTerm.length < 2) {
      this.searchResults = [];
      this.errorMessage = '';
      return;
    }

    // Debounce: wait 300ms before calling Apex
    this.debounceTimer = setTimeout(() => {
      this.performSearch(searchTerm);
    }, 300);
  }

  performSearch(searchTerm) {
    if (!this.isConnected) {
      return;
    }

    // Increment request ID to track latest request
    const currentRequestId = ++this.latestRequestId;

    // Call Apex imperatively
    searchContacts({ searchTerm })
      .then((result) => {
        // Only update results if this is the latest request and component is still connected
        if (currentRequestId === this.latestRequestId && this.isConnected) {
          this.searchResults = result;
          this.errorMessage = '';
        }
      })
      .catch((error) => {
        // Only update error if this is the latest request and component is still connected
        if (currentRequestId === this.latestRequestId && this.isConnected) {
          this.searchResults = [];
          this.errorMessage = error.body?.message || 'An error occurred';
        }
      });
  }
}
