    },
    {
      type: 'action',
      typeAttributes: {
        rowActions: [
          { label: 'View', name: 'view' },
          { label: 'Edit', name: 'edit' },
          { label: 'Delete', name: 'delete' }
        ]
      }
    }
  ];

  localOpportunities = [];

  connectedCallback() {
    this.updateLocalOpportunities();
  }

  @api
  get opportunities() {
    return this._opportunities;
  }

  set opportunities(value) {
    this._opportunities = value;
    this.updateLocalOpportunities();
  }

  _opportunities = [];

  updateLocalOpportunities() {
    // Create a shallow copy to avoid mutating parent's array
    this.localOpportunities = [...(this._opportunities || [])];
  }

  handleRowAction(event) {
    const action = event.detail.action.name;
    const row = event.detail.row;

    switch (action) {
      case 'view':
        this.handleView(row);
        break;
      case 'edit':
        this.handleEdit(row);
        break;
      case 'delete':
        this.handleDelete(row);
        break;
      default:
        break;
    }
  }

  handleView(row) {
    this[NavigationMixin.Navigate]({
      type: 'standard__recordPage',
      attributes: {
        recordId: row.Id,
        actionName: 'view'
      }
    });
  }

  handleEdit(row) {
    this[NavigationMixin.Navigate]({
      type: 'standard__recordPage',
      attributes: {
        recordId: row.Id,
        actionName: 'edit'
      }
    });
  }

  async handleDelete(row) {
    const confirmed = await LightningConfirm.open({
      message: `Are you sure you want to delete the opportunity "${row.Name}"?`,
      label: 'Confirm Delete'
    });

    if (!confirmed) {
      return;
    }

    try {
      await deleteRecord(row.Id);

      // Remove the row from the local table without mutating parent's array
      this.localOpportunities = this.localOpportunities.filter(
        (opp) => opp.Id !== row.Id
      );

      this.dispatchEvent(
        new ShowToastEvent({
          title: 'Opportunity deleted',
          variant: 'success'
        })
      );
    } catch (error) {
      const errorMessage =
        error.body && error.body.message
          ? error.body.message
          : 'An error occurred';

      this.dispatchEvent(
        new ShowToastEvent({
          title: 'Delete failed',
          message: errorMessage,
          variant: 'error'
        })
      );
    }
  }
}
