import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];
    showError = false;

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach(editor => {
            editor.reset();
        });
    }

    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        const validationResults = [];

        // Validate all editors, collecting results
        editors.forEach(editor => {
            validationResults.push(editor.validate());
        });

        // Check if all are valid
        const allValid = validationResults.every(result => result === true);

        if (allValid) {
            // Collect values from all editors in order
            const lineValues = [];
            editors.forEach(editor => {
                lineValues.push(editor.getValue());
            });

            // Dispatch submit event
            this.dispatchEvent(new CustomEvent('submit', {
                detail: { lines: lineValues }
            }));

            // Hide error message
            this.showError = false;
        } else {
            // Show error message
            this.showError = true;
        }
    }
}
