```html
<template>
  <div class="queue-monitor">
    <template if:true={waiting}>
      <p class="waiting">{waiting} waiting</p>
    </template>

    <template if:true={longestWaitMinutes}>
      <p class="longest">Longest wait: {longestWaitMinutes} min</p>
    </template>

    <template if:true={error}>
      <p class="error">{error.message}</p>
    </template>
  </div>
</template>
