import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

export default class EventRegistrationForm extends LightningElement {
	fullName = '';
	email = '';
	company = '';

	handleFieldChange(event) {
		const fieldName = event.target.dataset.field;
		if (fieldName) {
			this[fieldName] = event.detail.value;
		}
	}

	handleRegister() {
		// Step 1: Validate email domain and set custom validity
		const emailInput = this.template.querySelector(
			'lightning-input[data-field="email"]'
		);
		const emailDomain = this.getEmailDomain(this.email);
		const blockedDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

		if (blockedDomains.includes(emailDomain.toLowerCase())) {
			emailInput.setCustomValidity('Use your work email address.');
		} else {
			emailInput.setCustomValidity('');
		}

		// Step 2: Report validity on all inputs
		const allInputs = this.template.querySelectorAll('lightning-input');
		let isValid = true;
		allInputs.forEach((input) => {
			if (!input.reportValidity()) {
				isValid = false;
			}
		});

		// Step 3: Stop if any input is invalid
		if (!isValid) {
			return;
		}

		// Step 4: Call register imperatively
		register({
			fullName: this.fullName,
			email: this.email,
			company: this.company
		})
			.then(() => {
				this.dispatchEvent(
					new ShowToastEvent({
						variant: 'success',
						title: 'Registered'
					})
				);
				this.resetForm();
			})
			.catch((error) => {
				this.dispatchEvent(
					new ShowToastEvent({
						variant: 'error',
						title: 'Registration failed',
						message: error.body.message
					})
				);
			});
	}

	getEmailDomain(emailAddress) {
		const parts = emailAddress.split('@');
		return parts.length === 2 ? parts[1] : '';
	}

	resetForm() {
		this.fullName = '';
		this.email = '';
		this.company = '';
		const allInputs = this.template.querySelectorAll('lightning-input');
		allInputs.forEach((input) => {
			input.value = '';
		});
	}
}
