public with sharing class ContactImportService {
    /**
     * Imports a list of contacts, applying all Contact trigger actions except
     * TA_Contact_CreateWelcomeTask. This allows phone formatting to run while
     * preventing unwanted welcome task creation for legacy customer imports.
     *
     * @param contacts The list of contacts to insert
     * @throws DmlException if the insert operation fails
     */
    public static void importContacts(List<Contact> contacts) {
        // Bypass the welcome task creation action for this import
        MetadataTriggerHandler.bypass('TA_Contact_CreateWelcomeTask');

        try {
            // Insert all contacts in a single DML statement
            // The phone formatting action will still run
            insert contacts;
        } finally {
            // Always clear the bypass, even if insert fails
            MetadataTriggerHandler.clearBypass('TA_Contact_CreateWelcomeTask');
        }
    }
}
